#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn every_field_matches_original_std140_offsets() {
        assert_eq!(std::mem::size_of::<Globals>(), 4320);
        assert_eq!(std::mem::align_of::<Globals>(), 16);
        assert_eq!(std::mem::offset_of!(Globals, dims), 0);
        assert_eq!(std::mem::offset_of!(Globals, faces), 16);
        assert_eq!(std::mem::offset_of!(Globals, caps), 32);
        assert_eq!(std::mem::offset_of!(Globals, flags), 48);
        assert_eq!(std::mem::offset_of!(Globals, gravityDt), 64);
        assert_eq!(std::mem::offset_of!(Globals, simA), 80);
        assert_eq!(std::mem::offset_of!(Globals, simB), 96);
        assert_eq!(std::mem::offset_of!(Globals, wwA), 112);
        assert_eq!(std::mem::offset_of!(Globals, wwB), 128);
        assert_eq!(std::mem::offset_of!(Globals, wwC), 144);
        assert_eq!(std::mem::offset_of!(Globals, wwD), 160);
        assert_eq!(std::mem::offset_of!(Globals, proj), 176);
        assert_eq!(std::mem::offset_of!(Globals, view), 240);
        assert_eq!(std::mem::offset_of!(Globals, invProj), 304);
        assert_eq!(std::mem::offset_of!(Globals, invView), 368);
        assert_eq!(std::mem::offset_of!(Globals, domainOrigin), 432);
        assert_eq!(std::mem::offset_of!(Globals, screen), 448);
        assert_eq!(std::mem::offset_of!(Globals, sunDir), 464);
        assert_eq!(std::mem::offset_of!(Globals, skyColor), 480);
        assert_eq!(std::mem::offset_of!(Globals, fogColor), 496);
        assert_eq!(std::mem::offset_of!(Globals, waterA), 512);
        assert_eq!(std::mem::offset_of!(Globals, absorb), 528);
        assert_eq!(std::mem::offset_of!(Globals, scatter), 544);
        assert_eq!(std::mem::offset_of!(Globals, foamA), 560);
        assert_eq!(std::mem::offset_of!(Globals, ent), 576);
        assert_eq!(std::mem::offset_of!(Globals, sources), 2112);
        assert_eq!(std::mem::offset_of!(Globals, camGrid), 3136);
        assert_eq!(std::mem::offset_of!(Globals, misc), 3152);
        assert_eq!(std::mem::offset_of!(Globals, fine), 3168);
        assert_eq!(std::mem::offset_of!(Globals, surf), 3184);
        assert_eq!(std::mem::offset_of!(Globals, boxMin), 3200);
        assert_eq!(std::mem::offset_of!(Globals, boxMax), 3216);
        assert_eq!(std::mem::offset_of!(Globals, fineBoxMin), 3232);
        assert_eq!(std::mem::offset_of!(Globals, fineBoxMax), 3248);
        assert_eq!(std::mem::offset_of!(Globals, removeInfo), 3264);
        assert_eq!(std::mem::offset_of!(Globals, removeBox), 3280);
        assert_eq!(std::mem::offset_of!(Globals, killInfo), 3792);
        assert_eq!(std::mem::offset_of!(Globals, shadeA), 3808);
        assert_eq!(std::mem::offset_of!(Globals, shadeB), 3824);
        assert_eq!(std::mem::offset_of!(Globals, matA), 3840);
        assert_eq!(std::mem::offset_of!(Globals, matB), 3856);
        assert_eq!(std::mem::offset_of!(Globals, matC), 3872);
        assert_eq!(std::mem::offset_of!(Globals, matD), 3888);
        assert_eq!(std::mem::offset_of!(Globals, matE), 3904);
        assert_eq!(std::mem::offset_of!(Globals, compat), 3920);
        assert_eq!(std::mem::offset_of!(Globals, shadowNear), 3936);
        assert_eq!(std::mem::offset_of!(Globals, shadowMid), 4000);
        assert_eq!(std::mem::offset_of!(Globals, shadowFar), 4064);
        assert_eq!(std::mem::offset_of!(Globals, compatB), 4128);
        assert_eq!(std::mem::offset_of!(Globals, lightA), 4144);
        assert_eq!(std::mem::offset_of!(Globals, lightB), 4160);
        assert_eq!(std::mem::offset_of!(Globals, lightC), 4176);
        assert_eq!(std::mem::offset_of!(Globals, lightColors), 4192);
    }
    #[test]
    fn upload_is_little_endian_and_preserves_matrix_columns() {
        let mut g = Globals::zeroed();
        g.dims = [1, -2, 3, 4];
        g.proj[1][2] = 1.25;
        g.sources[63][3] = -4.0;
        let mut out = vec![0xFF; Globals::BYTE_SIZE];
        assert_eq!(g.write_le(&mut out), Ok(()));
        assert_eq!(&out[4..8], &(-2_i32).to_le_bytes());
        assert_eq!(&out[200..204], &(1.25_f32).to_le_bytes());
        assert_eq!(&out[3132..3136], &(-4.0_f32).to_le_bytes());
        assert_eq!(g.write_le(&mut []), Err(Globals::BYTE_SIZE));
    }
}
